scenario.en:
onMutate: async (todo) => {
  // MISSING: await queryClient.cancelQueries({ queryKey: ["todos"] });
  const previous = queryClient.getQueryData(["todos"]);
  queryClient.setQueryData(["todos"], (old) =>
    old.map((t) => (t.id === todo.id ? { ...t, done: true } : t))
  );
  return { previous };
}

